# Generate final output for submission using the transform function
def transform(grid):
    output = [[0] * 9 for _ in range(9)]

    patterns = {
        7: [(0, 0), (0, 2), (2, 0), (2, 2)],
        6: [(0, 0), (0, 1), (1, 0), (1, 2), (2, 1), (2, 2)],
        4: [(0, 2), (1, 0), (1, 1), (2, 0), (2, 1)],
        3: [(0, 0), (0, 1), (1, 0), (1, 1), (2, 0), (2, 1), (0, 2), (2, 2)]
    }

    for i in range(3):
        for j in range(3):
            if grid[i][j] > 0:
                color = grid[i][j]
                stamp_pattern = patterns.get(color, [(0, 0)])
                for r, c in stamp_pattern:
                    output[i * 3 + r][j * 3 + c] = color

    return output

